export function coverageByLanguage() {
  const out = {};
  for (const [ns, keys] of Object.entries(coverage)) {
    for (const [key, langs] of Object.entries(keys)) {
      for (const [lng, value] of Object.entries(langs)) {
        (out[lng] ??= {});
        (out[lng][ns] ??= {});
        out[lng][ns][key] = value;
      }
    }
  }
  return out;
}
